use std::mem::size_of;

use nara_asset::{AssetSlotRevision, Assets, Handle};
use nara_core::Mat3;
use nara_ecs::Entity;
use nara_image::ImageContentSnapshot;
use nara_material::Material2dBinding;
use nara_tilemap::{TileSet, Tilemap, TilemapCellRevision};

use crate::ExtractedSprite;

const MAX_MAPS: usize = 128;
const MAX_GEOMETRY_BYTES: usize = 32 * 1024 * 1024;

#[derive(Clone, PartialEq, Eq)]
pub(super) struct SourceKey {
    cells: TilemapCellRevision,
    matrix: [u32; 9],
    tile_size: [u32; 2],
    layer: i32,
    sort_key: i32,
    anchor: Option<[u32; 2]>,
    tileset: Option<(Handle<TileSet>, AssetSlotRevision)>,
}

impl SourceKey {
    pub(super) fn capture(
        tilemap: &Tilemap,
        matrix: Mat3,
        assets: Option<&Assets<TileSet>>,
    ) -> Self {
        Self {
            cells: tilemap.cell_revision(),
            matrix: matrix.to_cols_array().map(f32::to_bits),
            tile_size: tilemap.tile_size.to_array().map(f32::to_bits),
            layer: tilemap.layer.index,
            sort_key: tilemap.sort_key,
            anchor: tilemap
                .y_sort_anchor
                .map(|value| value.to_array().map(f32::to_bits)),
            tileset: tilemap
                .tileset
                .and_then(|handle| assets.map(|assets| (handle, assets.slot_revision(handle)))),
        }
    }
}

struct Geometry {
    sprites: Vec<ExtractedSprite>,
    charged_bytes: usize,
}

struct Entry {
    source: SourceKey,
    seen: bool,
    stable: bool,
    geometry: Option<Geometry>,
}

#[derive(Default)]
pub(super) struct TileGeometryReuse {
    entries: Vec<(Entity, Entry)>,
    geometry_bytes: usize,
}

impl std::fmt::Debug for TileGeometryReuse {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter
            .debug_struct("TileGeometryReuse")
            .field("maps", &self.entries.len())
            .field("geometry_bytes", &self.geometry_bytes)
            .finish()
    }
}

impl TileGeometryReuse {
    pub(super) fn clear(&mut self) {
        self.entries.clear();
        self.geometry_bytes = 0;
    }

    pub(super) fn begin(&mut self) {
        for (_, entry) in &mut self.entries {
            entry.seen = false;
        }
    }

    pub(super) fn append(
        &mut self,
        entity: Entity,
        source: SourceKey,
        output: &mut Vec<ExtractedSprite>,
        material: &Option<Material2dBinding>,
        image: Option<&ImageContentSnapshot>,
    ) -> bool {
        let Some(index) = self
            .entries
            .iter()
            .position(|(candidate, _)| *candidate == entity)
        else {
            if self.entries.len() < MAX_MAPS
                && (self.entries.capacity() >= MAX_MAPS
                    || self
                        .entries
                        .try_reserve_exact(MAX_MAPS - self.entries.len())
                        .is_ok())
            {
                self.entries.push((
                    entity,
                    Entry {
                        source,
                        seen: true,
                        stable: false,
                        geometry: None,
                    },
                ));
            }
            return false;
        };
        let entry = &mut self.entries[index].1;
        entry.seen = true;
        if entry.source != source {
            if let Some(geometry) = entry.geometry.take() {
                self.geometry_bytes -= geometry.charged_bytes;
            }
            entry.source = source;
            entry.stable = false;
            return false;
        }
        entry.stable = true;
        let Some(geometry) = entry.geometry.as_ref() else {
            return false;
        };
        for base in &geometry.sprites {
            let mut sprite = base.clone();
            sprite.source_order = output.len() as u64;
            sprite.material_extension = material.clone();
            sprite.image_content = image.cloned();
            output.push(sprite);
        }
        true
    }

    pub(super) fn retain(
        &mut self,
        entity: Entity,
        sprites: &[ExtractedSprite],
        invalid_regions: u32,
    ) {
        if invalid_regions != 0 {
            if let Some(index) = self
                .entries
                .iter()
                .position(|(candidate, _)| *candidate == entity)
                && let Some(geometry) = self.entries.remove(index).1.geometry
            {
                self.geometry_bytes -= geometry.charged_bytes;
            }
            return;
        }
        let Some((_, entry)) = self
            .entries
            .iter_mut()
            .find(|(candidate, _)| *candidate == entity)
        else {
            return;
        };
        if !entry.stable || entry.geometry.is_some() || sprites.is_empty() {
            return;
        }
        let Some(needed) = sprites.len().checked_mul(size_of::<ExtractedSprite>()) else {
            return;
        };
        if needed > MAX_GEOMETRY_BYTES.saturating_sub(self.geometry_bytes) {
            return;
        }
        let mut base = Vec::new();
        if base.try_reserve_exact(sprites.len()).is_err() {
            return;
        }
        let Some(charged_bytes) = base.capacity().checked_mul(size_of::<ExtractedSprite>()) else {
            return;
        };
        if charged_bytes > MAX_GEOMETRY_BYTES.saturating_sub(self.geometry_bytes) {
            return;
        }
        for sprite in sprites {
            let mut sprite = sprite.clone();
            sprite.material_extension = None;
            sprite.image_content = None;
            sprite.source_order = 0;
            base.push(sprite);
        }
        self.geometry_bytes += charged_bytes;
        entry.geometry = Some(Geometry {
            sprites: base,
            charged_bytes,
        });
    }

    pub(super) fn finish(&mut self) {
        self.entries.retain(|(_, entry)| {
            if !entry.seen {
                if let Some(geometry) = &entry.geometry {
                    self.geometry_bytes -= geometry.charged_bytes;
                }
                false
            } else {
                true
            }
        });
    }
}

