        let mut cache = TileGeometryReuse::default();
        let mut output = Vec::new();
        for index in 1..=MAX_MAPS + 1 {
            assert!(!cache.append(
                entity(index as u32),
                source.clone(),
                &mut output,
                &None,
                None
            ));
        }
        assert_eq!(cache.entries.len(), MAX_MAPS);
